<script>
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function filterRows(value){document.querySelectorAll('#accounts tbody tr').forEach(row=>row.hidden=!row.innerText.toLowerCase().includes(value.toLowerCase()))}
function reveal(){const el=document.getElementById('secret');el.innerHTML='orm-demo-credential <button class="action-link" onclick="mask()">Hide</button>'}
function mask(){document.getElementById('secret').innerHTML='•••••••••••••••• <button class="action-link" onclick="reveal()">Reveal</button>'}
</script>
</body></html>
